model_device = next(model.parameters()).device
print(model_device)

"""## **Important:**

Make sure that `temperature = 1 `and `top_k = 1` as we dont want any creativity and just want the exact answer.
"""

top_k = 1
temperature = 1
max_length = 256

def generate(token_ids, max_length, top_k, temperature, context_size):
  token_ids = token_ids.to(model_device)

  model.eval() # set model to evaluation mode (disables dropout)
  with torch.no_grad(): # disable gradient tracking (saves memory + compute)
    for i in range(max_length):
      logits = model(token_ids[:, -context_size:]) # shape: (batch_size, seq_len, vocab_size)
      logits = logits[:, -1, :]  # take logits for the last token (next-token prediction), shape: (batch_size, vocab_size)
      top_values, top_indices = torch.topk(logits, k=top_k)  # select top-k highest logits for each batch
      min_val = top_values[:, -1].unsqueeze(-1)#selects the minimum value from each example in batch
      logits = torch.where(
          condition = logits < min_val,
          input = torch.tensor(float('-inf'), device=logits.device), # or use -torch.inf.to(logits.device)
          other = logits
      )
      # only top-k tokens remain; others get -inf → zero probability after softmax
      scaled_logits = logits/temperature # scale logits to control randomness (temperature scaling)
      probs = torch.softmax(scaled_logits, dim = -1)
      next_token_id = torch.multinomial(probs, num_samples = 1)
      token_ids = torch.cat([token_ids, next_token_id], dim = -1)

  tokens = tokenizer.decode(token_ids.squeeze(0).tolist())
  print(tokens)

generate(token_ids, max_length, top_k, temperature, GPT_CONFIG_355M["context_length"])

"""### We can see that the output is not as expected as the model wasn't fine-tuned.

## Fine-Tune the model
"""

def cal_batch_loss(input_batch, target_batch, model):
  logits = model(input_batch)
  loss = nn.functional.cross_entropy(logits.flatten(0,1), target_batch.flatten())
  return loss #Mean loss per batch, returns a scalar tensor

def cal_loader_loss(loader, model):
  total_loss = 0.
  device = torch.device('cuda' if torch.cuda.is_available() else 'cpu')
  for input_batch, target_batch in loader:
    input_batch, target_batch = input_batch.to(device), target_batch.to(device)
    loss = cal_batch_loss(input_batch, target_batch, model)
    total_loss += loss.item() #.item() on it to get a plain Python float

  return total_loss/len(loader) #Mean batch loss across all batches

print(f'Train Loss: {cal_loader_loss(train_loader, model)}')
print(f'Val Loss: {cal_loader_loss(val_loader, model)}')

import matplotlib.pyplot as plt

def plot_losses(epochs_seen, train_losses, val_losses):
    plt.figure(figsize=(8, 5))
    plt.plot(epochs_seen, train_losses, label="Training loss")
    plt.plot(epochs_seen, val_losses, linestyle="--", label="Validation loss")
    plt.xlabel("Epochs")
    plt.ylabel("Loss")
    plt.legend()
    plt.tight_layout()
    plt.savefig("loss_plot.png", dpi=150)
    plt.show()

import time
model_device = next(model.parameters()).device
optimizer = torch.optim.AdamW(model.parameters(), lr = 0.00005, weight_decay = 0.1)
model.to(model_device) # modifies the model in-place — its internal tensors are moved
train_losses, val_losses, epochs_seen, running_train_batch_losses, running_val_batch_losses = [], [], [], [], []

start_time = time.time()

model.train() #enables dropout
for epoch in range(2): #more epochs will diverge validation and train loss
  total_loss = 0.
  for i, (input_batch, target_batch) in enumerate(train_loader):
    input_batch, target_batch = input_batch.to(device), target_batch.to(device) #doesnt modify in-place, so reassigned
    optimizer.zero_grad()
    loss = cal_batch_loss(input_batch, target_batch, model)
    loss.backward()  #Runs backpropagation, Just computes and stores gradients.
    optimizer.step() #update weights
    total_loss += loss.item() #tensor --> float


    if(i%50 == 0):
      running_avg_loss = total_loss / (i + 1)
      print(f'\nEpoch {epoch+1}:  ')
      print(f'Train Loss after batch {i}: {running_avg_loss:.4f}')
      running_train_batch_losses.append(running_avg_loss)

      model.eval()
      with torch.no_grad():  # no computation graph created - no memory wasted
        val_loss = cal_loader_loss(val_loader, model)
      print(f'Val Loss after batch {i}: {val_loss:.4f}')
      running_val_batch_losses.append(val_loss)

      model.train()

   # Track losses
  train_losses.append(total_loss/len(train_loader))
  val_losses.append(val_loss)
  epochs_seen.append(epoch + 1)

  model.train()

end_time = time.time()
execution_time_minutes = (end_time - start_time) / 60
print(f'Total Training Time: {execution_time_minutes:.2f} minutes')

